      body: "브라우저만 있으면 바로 실행되고 결과가 눈에 보이기 때문에 자바스크립트는 흥미를 붙이기 좋은 언어예요. 버튼을 누르면 색이 바뀌고 숫자가 올라가는 걸 직접 만들면 성취감이 큽니다. 그런데 이 즉각적인 피드백이 함정이 되기도 해요. 코드를 복사해 붙여서 동작하면 이해했다고 착각하기 쉽고, 조금만 상황이 바뀌면 손을 못 대는 상태가 됩니다. 특히 자바스크립트는 유연한 문법 탓에 '되긴 되는데 왜 되는지 모르는' 경우가 많아요. 학습 단계: (1) 기본 문법과 자료형 → (2) 함수와 스코프로 구조화 → (3) DOM·이벤트로 화면 제어 → (4) 비동기와 실전 프로젝트. 1:1 수업에서는 동작 여부만 확인하지 않고, 학생이 자기 코드를 직접 설명하도록 하며 진짜 이해했는지 함께 점검해요.",
