      body: "웹 페이지의 뼈대를 만드는 HTML과 옷을 입히는 CSS는 코딩 입문에서 가장 진입 장벽이 낮아요. 태그 몇 개만 알면 화면에 글자가 나오니 첫 성취감도 빠릅니다. 문제는 그다음이에요. 태그는 외웠는데 요소가 원하는 위치에 안 가고, 가운데 정렬 하나에 몇 시간을 쓰게 됩니다. 이건 태그를 몰라서가 아니라 브라우저가 요소를 어떻게 쌓고 배치하는지 그 원리를 모르기 때문이에요. 박스 모델과 레이아웃 원리를 이해하면 이 답답함이 대부분 사라집니다. 학습 단계: (1) HTML 구조와 시맨틱 태그 → (2) CSS 선택자와 박스 모델 → (3) 레이아웃으로 배치 설계 → (4) 반응형으로 다양한 화면 대응. 1:1 수업에서는 '이렇게 하면 됩니다' 대신 왜 그렇게 배치되는지 함께 뜯어보며 스스로 해결하는 힘을 길러 드려요.",
