    checklistTitle: "HTML·CSS 학습 체크리스트",
    checklistSub: "월 1회 점검",
    faqs: [
      { q: "HTML·CSS도 프로그래밍인가요?", a: "엄밀히는 프로그래밍 언어가 아니에요. HTML은 구조를 표현하는 마크업, CSS는 스타일을 지정하는 언어라 조건·반복 같은 논리 흐름이 없습니다. 하지만 웹을 다루려면 반드시 필요한 기초이고, 결과가 눈에 보여 코딩 입문의 부담을 낮춰줘요. 이후 자바스크립트로 넘어가면 진짜 프로그래밍이 시작됩니다. 1:1 상담에서 학생 목표에 맞는 학습 순서를 정해 드려요." },
      { q: "얼마나 배워야 페이지를 만들 수 있나요?", a: "간단한 페이지는 기초만 익혀도 만들 수 있어요. 다만 '원하는 대로' 만들려면 배치 원리를 이해하는 시간이 필요합니다. 대부분 태그 암기가 아니라 레이아웃에서 시간을 쓰게 돼요. 학생마다 속도가 달라 기간을 단정하기 어렵지만, 원리 중심으로 배우면 훨씬 빨라집니다. 1:1 수업에서 학생 수준에 맞춰 진행해 드립니다." },
      { q: "초등학생도 배울 수 있나요?", a: "가능하지만 영어와 타자에 대한 부담을 봐야 해요. 태그가 영어 단어라 읽고 쓰는 게 어려우면 진도가 잘 안 나갑니다. 블록 코딩으로 프로그래밍 개념을 먼저 접한 뒤 넘어오는 경우가 많아요. 다만 관심이 크고 준비가 된 학생은 충분히 시작할 수 있습니다. 1:1 상담에서 학생 상태를 확인해 드릴게요." },
      { q: "수업은 어떻게 진행되나요?", a: "학생이 직접 화면을 만들어보는 과정을 중심으로 진행해요. 원하는 배치가 안 될 때 답을 바로 알려주기보다, 왜 그렇게 그려지는지 함께 확인하며 스스로 찾도록 이끕니다. 결과물이 나오면 다양한 화면 크기로 함께 점검해요. 학생 목표와 수준에 따라 커리큘럼은 맞춤 조정됩니다." },
      { q: "자바스크립트는 언제 배우나요?", a: "HTML·CSS로 화면을 만들 수 있게 되면 자연스럽게 넘어갈 시점이에요. 정지된 화면에 움직임과 상호작용을 넣고 싶어질 때가 적기입니다. 완벽히 마스터한 뒤 넘어갈 필요는 없고, 기본 구조와 스타일을 다룰 수 있으면 병행해도 좋아요. 1:1 상담에서 학생 상황에 맞춰 시점을 함께 정해 드립니다." },
    ],
