      body: "코딩테스트나 대회를 준비하며 가장 많이 하는 게 '문제 많이 풀기'예요. 그런데 수백 문제를 풀어도 처음 보는 문제 앞에서 여전히 막막한 경우가 많습니다. 이유는 풀이를 외웠기 때문이에요. 답을 보고 이해하면 그 문제는 알게 되지만, 그 답에 도달하는 사고 과정은 배우지 못합니다. 알고리즘 실력은 아는 유형의 개수가 아니라 처음 보는 문제를 분석하고 접근법을 찾는 힘이에요. 이건 문법 지식과 완전히 다른 능력이고, 훈련 방식도 달라야 합니다. 학습 단계: (1) 자료구조 이해 → (2) 기본 알고리즘 원리 → (3) 문제 분석과 접근법 훈련 → (4) 효율성과 실전 대응. 1:1 수업에서는 정답 코드를 알려주기보다 문제를 어떻게 뜯어보는지 그 과정을 함께 훈련해 드려요.",
