      body: "2022 개정 교육과정에서 정보 교과의 비중이 커졌어요. 시수가 늘고 디지털 소양이 강조되면서 학교에서 다루는 범위도 넓어졌습니다. 문제는 '그래서 무엇이 달라지고 무엇을 준비해야 하나'가 잘 안 보인다는 거예요. 시수가 늘었다는 소식은 들었는데 정작 무엇을 배우고 어떻게 평가받는지는 막연합니다. 게다가 학교마다 운영 방식이 달라서 일반적인 정보만으로는 대비가 어려워요. 확실한 건 정보 교과가 예전보다 중요해졌고, 평가 방식도 단순 암기보다 문제 해결 과정을 보는 쪽으로 가고 있다는 점입니다. 학습 단계: (1) 학교급별 변화 파악 → (2) 우리 학교 운영 확인 → (3) 컴퓨팅 사고력 다지기 → (4) 평가 형태에 맞춰 대비. 1:1 수업에서는 학생이 실제로 배우는 내용에 맞춰 필요한 준비를 해 드려요.",
